def _backfill_legacy_payments(apps, schema_editor):
    """
    ADR p27 / contrato §10: por cada factura ya `paid` (con total > 0) crea un
    Payment `legacy` que liquida el total. `actor=NULL` (no inventar actores),
    `occurred_at=Invoice.paid_at`, `idempotency_key=NULL`.

    Salta facturas con total <= 0 (degeneradas, ej. 100% descuento): no hubo
    dinero, no corresponde un Payment, y violaría el CHECK amount > 0.
    """
    Invoice = apps.get_model('billing', 'Invoice')
    Payment = apps.get_model('billing', 'Payment')

    batch = []
    qs = Invoice.objects.filter(
        status='paid', paid_at__isnull=False, total__gt=0
    ).iterator()
    for inv in qs:
        batch.append(Payment(
            organization_id=inv.organization_id,
            invoice_id=inv.pk,
            amount=inv.total,
            method=inv.payment_method or 'other',
            occurred_at=inv.paid_at,
            actor_id=None,
            provenance='legacy',
            idempotency_key=None,
        ))
        if len(batch) >= 500:
            Payment.objects.bulk_create(batch)
            batch = []
    if batch:
        Payment.objects.bulk_create(batch)


def _reverse_backfill(apps, schema_editor):
    Payment = apps.get_model('billing', 'Payment')
    Payment.objects.filter(provenance='legacy').delete()


